import { toSrgb } from './colour.ts'
import type { CubicBezier } from './dtcg.ts'
import {
  DENSITY_MODES,
  MOTION_MODES,
  cssVar,
  cubicBezierCss,
  type Density,
  type Motion,
  type MotionMode,
  type RoleValue,
} from './model.ts'
import { COLOUR_MODES, fontCss, type Theme } from './theme.ts'

const NOTICE =
  'Generated by tokens/src/cli.ts from tokens/source. Edit the source, then run pnpm tokens:write.'

function block(selector: string, lines: string[]): string {
  return `${selector} {\n${lines.map(line => `  ${line}`).join('\n')}\n}`
}

function roleLines(role: string, value: RoleValue): string[] {
  if (value.kind === 'jump') {
    // A jump has no curve to follow; linear is the easing of a zero-length change.
    return [
      `${cssVar(role, 'duration')}: ${value.durationMs}ms;`,
      `${cssVar(role, 'easing')}: linear;`,
    ]
  }
  if (value.kind === 'spring') {
    return [
      `${cssVar(role, 'duration')}: ${value.duration.css};`,
      `${cssVar(role, 'easing')}: ${value.easing.css};`,
    ]
  }
  const lines = [
    `${cssVar(role, 'duration')}: ${value.duration.css};`,
    `${cssVar(role, 'easing')}: ${value.easingCss.css};`,
  ]
  if (value.offset) lines.push(`${cssVar(role, 'offset')}: ${value.offset.css};`)
  if (value.scaleCss) lines.push(`${cssVar(role, 'scale')}: ${value.scaleCss.css};`)
  return lines
}

function modeLines(motion: Motion, mode: MotionMode): string[] {
  const { roles, stagger } = motion.modes[mode]
  return [
    ...motion.roles.flatMap(role => roleLines(role, roles[role] as RoleValue)),
    `--nk-stagger-step: ${stagger.step.css};`,
    `--nk-stagger-max: ${stagger.max.css};`,
  ]
}

/** registry/styles/motion.css: primitives, then the roles for each mode (FR-M7, FR-M9 to FR-M11, FR-M16). */
export function motionCss(motion: Motion): string {
  const { primitives } = motion
  const primitiveLines = [
    ...primitives.durations.map(d => `${cssVar(d.name)}: ${d.ms}ms;`),
    ...primitives.easings.map(e => `${cssVar(e.name)}: ${cubicBezierCss(e.value)};`),
    ...primitives.springs.flatMap(s => [
      `${cssVar(s.primitive, 'duration')}: ${s.settleMs}ms;`,
      `${cssVar(s.primitive, 'easing')}: ${s.linear};`,
    ]),
    ...primitives.offsets.map(o => `${cssVar(o.name)}: ${o.px}px;`),
    ...primitives.scales.map(s => `${cssVar(s.name)}: ${s.value};`),
    ...primitives.staggers.map(s => `${cssVar(s.name)}: ${s.ms}ms;`),
  ]
  const reduced = modeLines(motion, 'reduced')
  return [
    `/* ${NOTICE} */`,
    '',
    '/* Primitives. Components never read these; the role variables below do. */',
    block(':root', primitiveLines),
    '',
    '/* Subtle, the default theme. Redeclared on [data-motion] so a subtree can switch back. */',
    block(":root,\n[data-motion='subtle']", modeLines(motion, 'subtle')),
    '',
    block("[data-motion='expressive']", modeLines(motion, 'expressive')),
    '',
    '/* Reduced motion overrides any theme (FR-M11), so it comes last. */',
    `@media (prefers-reduced-motion: reduce) {\n${block(':root,\n[data-motion]', reduced)
      .split('\n')
      .map(line => `  ${line}`)
      .join('\n')}\n}`,
    '',
    '/* Forced, for docs and tests (FR-M10). */',
    block('[data-motion-reduce],\n[data-motion-reduce] [data-motion]', reduced),
    '',
  ].join('\n')
}

function rem(px: number): string {
  return `${Number((px / 16).toFixed(4))}rem`
}

/** registry/styles/density.css: comfortable on the root, compact on data-density (FR-V5). */
export function densityCss(density: Density): string {
  const lines = (mode: (typeof DENSITY_MODES)[number]) =>
    density.tokens.map(
      token => `${cssVar(token.name.slice('density.'.length))}: ${rem(token.px[mode])};`,
    )
  return [
    `/* ${NOTICE} */`,
    '',
    block(":root,\n[data-density='comfortable']", lines('comfortable')),
    '',
    block("[data-density='compact']", lines('compact')),
    '',
  ].join('\n')
}

function transitionFor(value: RoleValue): string {
  if (value.kind === 'spring') {
    return `{ type: 'spring', visualDuration: ${value.spring.visualDurationMs / 1000}, bounce: ${value.spring.bounce} }`
  }
  if (value.kind === 'jump') return `{ duration: 0 }`
  return `{ duration: ${value.durationMs / 1000}, ease: [${value.easing.join(', ')}] }`
}

function roleTokenFor(value: RoleValue): string {
  if (value.kind === 'jump') return `{ durationMs: ${value.durationMs}, easing: 'linear' }`
  if (value.kind === 'spring') {
    const { spring } = value
    return `{ durationMs: ${spring.settleMs}, easing: '${spring.linear}', visualDurationMs: ${spring.visualDurationMs}, bounce: ${spring.bounce} }`
  }
  const parts = [`durationMs: ${value.durationMs}`, `easing: '${cubicBezierCss(value.easing)}'`]
  if (value.offsetPx !== undefined) parts.push(`offsetPx: ${value.offsetPx}`)
  if (value.scale !== undefined) parts.push(`scale: ${value.scale}`)
  return `{ ${parts.join(', ')} }`
}

/** packages/engine/src/tokens.generated.ts: the token runtime and the Motion adapter (FR-M5). */
export function engineTs(motion: Motion): string {
  const capLines = motion.roles.map(role => `  '${role}': ${motion.caps[role]},`)
  const perMode = (render: (value: RoleValue) => string) =>
    MOTION_MODES.map(mode => {
      const roles = motion.roles.map(
        role => `    '${role}': ${render(motion.modes[mode].roles[role] as RoleValue)},`,
      )
      return `  ${mode}: {\n${roles.join('\n')}\n  },`
    }).join('\n')
  const staggerLines = MOTION_MODES.map(mode => {
    const { step, max } = motion.modes[mode].stagger
    return `  ${mode}: { stepMs: ${step.ms}, maxMs: ${max.ms} },`
  })
  const { limits } = motion
  return [
    `// ${NOTICE}`,
    '',
    '/** Upper limit on duration per role, in ms (FR-M13). A spring role is measured by its visual duration. */',
    'export const DURATION_CAPS_MS = {',
    ...capLines,
    '} as const',
    '',
    'export type MotionRole = keyof typeof DURATION_CAPS_MS',
    '',
    '/** The two themes, plus reduced motion, which overrides either (FR-M11). */',
    `export const MOTION_MODES = [${MOTION_MODES.map(mode => `'${mode}'`).join(', ')}] as const`,
    '',
    'export type MotionMode = (typeof MOTION_MODES)[number]',
    '',
    '/** Global limits every theme stays inside (FR-M13). */',
    'export const MOTION_LIMITS = {',
    `  bounceMax: ${limits.bounceMax},`,
    `  offsetMaxPx: ${limits.offsetMaxPx},`,
    `  scaleMin: ${limits.scaleMin},`,
    `  reducedDurationMaxMs: ${limits.reducedDurationMaxMs},`,
    '} as const',
    '',
    'export interface RoleToken {',
    '  /** How long the CSS transition runs; for a spring, until it settles. */',
    '  durationMs: number',
    '  /** A CSS easing: cubic-bezier(), linear() for a spring, or linear for a jump. */',
    '  easing: string',
    '  offsetPx?: number',
    '  scale?: number',
    '  visualDurationMs?: number',
    '  bounce?: number',
    '}',
    '',
    '/** Every role in every mode, resolved to values. The same values as the CSS custom properties. */',
    'export const MOTION_TOKENS: Record<MotionMode, Record<MotionRole, RoleToken>> = {',
    perMode(roleTokenFor),
    '}',
    '',
    '/** Stagger on first open, per mode (FR-S21). */',
    'export const STAGGER: Record<MotionMode, { stepMs: number; maxMs: number }> = {',
    ...staggerLines,
    '}',
    '',
    '/** A transition in the shape Motion takes: seconds, a cubic-bezier array, or a spring. */',
    'export type MotionTransition =',
    "  | { type: 'spring'; visualDuration: number; bounce: number }",
    '  | { duration: number; ease?: [number, number, number, number] }',
    '',
    '/** The Motion adapter: each role in each mode as a Motion transition (FR-M4, FR-M15). */',
    'export const MOTION_TRANSITIONS: Record<MotionMode, Record<MotionRole, MotionTransition>> = {',
    perMode(transitionFor),
    '}',
    '',
  ].join('\n')
}

interface FigmaVariable {
  action: 'CREATE'
  id: string
  name: string
  variableCollectionId: string
  resolvedType: 'FLOAT' | 'TIMING' | 'EASING' | 'COLOR' | 'STRING'
  scopes: string[]
  codeSyntax?: { WEB: string }
  description?: string
}

/** Figma's easing value: a cubic bezier, a spring defined by its bounce, or linear. */
type FigmaEasing =
  | {
      type: 'CUSTOM_CUBIC_BEZIER'
      easingFunctionCubicBezier: { x1: number; y1: number; x2: number; y2: number }
    }
  | { type: 'CUSTOM_SPRING'; easingFunctionSpring: { bounce: number } }
  | { type: 'LINEAR' }

type FigmaValue =
  number | string | FigmaEasing | { r: number; g: number; b: number; a: number } | { alias: string }

function bezier([x1, y1, x2, y2]: CubicBezier): FigmaEasing {
  return { type: 'CUSTOM_CUBIC_BEZIER', easingFunctionCubicBezier: { x1, y1, x2, y2 } }
}

/** Figma's TIMING variables hold seconds. */
const seconds = (ms: number) => ms / 1000

/**
 * tokens/generated/figma-variables.json, in the shape of the body of Figma's
 * POST /v1/files/:key/variables. Ids are temporary ids that tie the entries
 * together; the Figma build reads this file and creates the variables.
 *
 * Durations are TIMING variables and easings are EASING variables, Figma's
 * own motion types. A spring is a TIMING variable holding its visual duration
 * and an EASING variable holding its bounce, which is how Figma and Motion
 * both define a spring.
 */
export function figmaVariables(motion: Motion, density: Density, theme: Theme): string {
  const collections: object[] = []
  const modes: object[] = []
  const variables: FigmaVariable[] = []
  const values: object[] = []

  const collection = (key: string, name: string, modeNames: string[]) => {
    const id = `collection:${key}`
    collections.push({ action: 'CREATE', id, name, initialModeId: `mode:${key}:${modeNames[0]}` })
    modeNames.forEach((mode, i) => {
      modes.push({
        action: i === 0 ? 'UPDATE' : 'CREATE',
        id: `mode:${key}:${mode}`,
        name: mode[0]?.toUpperCase() + mode.slice(1),
        variableCollectionId: id,
      })
    })
    return id
  }
  const variable = (
    collectionId: string,
    name: string,
    type: FigmaVariable['resolvedType'],
    /** The custom property it matches, or null where the CSS holds a different value. */
    web: string | null,
    scopes: string[],
    description?: string,
  ) => {
    const id = `variable:${name}`
    variables.push({
      action: 'CREATE',
      id,
      name,
      variableCollectionId: collectionId,
      resolvedType: type,
      scopes,
      ...(web ? { codeSyntax: { WEB: `var(${web})` } } : {}),
      ...(description ? { description } : {}),
    })
    return id
  }
  const set = (variableId: string, modeId: string, value: FigmaValue) => {
    values.push({
      variableId,
      modeId,
      value:
        typeof value === 'object' && 'alias' in value
          ? { type: 'VARIABLE_ALIAS', id: `variable:${value.alias}` }
          : value,
    })
  }
  const slash = (name: string) => name.split('.').join('/')

  const primitives = collection('primitives', 'nimki/primitives', ['value'])
  const p = 'mode:primitives:value'
  for (const d of motion.primitives.durations) {
    set(variable(primitives, slash(d.name), 'TIMING', cssVar(d.name), []), p, seconds(d.ms))
  }
  for (const e of motion.primitives.easings) {
    set(variable(primitives, slash(e.name), 'EASING', cssVar(e.name), []), p, bezier(e.value))
  }
  for (const s of motion.primitives.springs) {
    const base = slash(s.primitive)
    // The CSS runs a spring for its settle time, not its visual duration, so the
    // duration has no matching custom property. The easing does: the CSS
    // linear() is sampled from the same spring.
    set(
      variable(primitives, `${base}/duration`, 'TIMING', null, []),
      p,
      seconds(s.visualDurationMs),
    )
    set(variable(primitives, `${base}/easing`, 'EASING', cssVar(s.primitive, 'easing'), []), p, {
      type: 'CUSTOM_SPRING',
      easingFunctionSpring: { bounce: s.bounce },
    })
  }
  for (const o of motion.primitives.offsets) {
    set(variable(primitives, slash(o.name), 'FLOAT', cssVar(o.name), []), p, o.px)
  }
  for (const s of motion.primitives.scales) {
    set(variable(primitives, slash(s.name), 'FLOAT', cssVar(s.name), []), p, s.value)
  }
  for (const s of motion.primitives.staggers) {
    set(variable(primitives, slash(s.name), 'TIMING', cssVar(s.name), []), p, seconds(s.ms))
  }

  const motionId = collection('motion', 'nimki/motion', [...MOTION_MODES])
  // Each role variable is an alias of the primitive the CSS points at, so a
  // primitive changed in Figma moves every role that uses it, as in the CSS.
  const aliasOrValue = (css: string, value: FigmaValue): FigmaValue => {
    const name = variables.find(v => v.codeSyntax?.WEB === css)?.name
    return name ? { alias: name } : value
  }
  for (const role of motion.roles) {
    const first = motion.modes.subtle.roles[role] as RoleValue
    if (first.kind === 'spring') {
      const duration = variable(motionId, `${role}/duration`, 'TIMING', null, [])
      const easing = variable(motionId, `${role}/easing`, 'EASING', cssVar(role, 'easing'), [])
      for (const mode of MOTION_MODES) {
        const value = motion.modes[mode].roles[role] as RoleValue
        const modeId = `mode:motion:${mode}`
        if (value.kind === 'spring') {
          set(duration, modeId, { alias: `${slash(value.spring.primitive)}/duration` })
          set(easing, modeId, { alias: `${slash(value.spring.primitive)}/easing` })
        } else {
          // Reduced motion: the change happens at once.
          set(duration, modeId, seconds(value.durationMs))
          set(easing, modeId, { type: 'LINEAR' })
        }
      }
      continue
    }
    const ids = {
      duration: variable(motionId, `${role}/duration`, 'TIMING', cssVar(role, 'duration'), []),
      easing: variable(motionId, `${role}/easing`, 'EASING', cssVar(role, 'easing'), []),
      offset:
        first.kind === 'tween' && first.offset
          ? variable(motionId, `${role}/offset`, 'FLOAT', cssVar(role, 'offset'), [])
          : undefined,
      scale:
        first.kind === 'tween' && first.scaleCss
          ? variable(motionId, `${role}/scale`, 'FLOAT', cssVar(role, 'scale'), [])
          : undefined,
    }
    for (const mode of MOTION_MODES) {
      const value = motion.modes[mode].roles[role] as RoleValue
      if (value.kind !== 'tween') continue
      const modeId = `mode:motion:${mode}`
      set(ids.duration, modeId, aliasOrValue(value.duration.css, seconds(value.durationMs)))
      set(ids.easing, modeId, aliasOrValue(value.easingCss.css, bezier(value.easing)))
      if (ids.offset && value.offset) {
        set(ids.offset, modeId, aliasOrValue(value.offset.css, value.offsetPx as number))
      }
      if (ids.scale && value.scaleCss) {
        set(ids.scale, modeId, aliasOrValue(value.scaleCss.css, value.scale as number))
      }
    }
  }
  const stagger = {
    step: variable(motionId, 'stagger/step', 'TIMING', '--nk-stagger-step', []),
    max: variable(motionId, 'stagger/max', 'TIMING', '--nk-stagger-max', []),
  }
  for (const mode of MOTION_MODES) {
    const { step, max } = motion.modes[mode].stagger
    set(stagger.step, `mode:motion:${mode}`, aliasOrValue(step.css, seconds(step.ms)))
    set(stagger.max, `mode:motion:${mode}`, aliasOrValue(max.css, seconds(max.ms)))
  }

  const densityId = collection('density', 'nimki/density', [...DENSITY_MODES])
  for (const token of density.tokens) {
    const short = token.name.slice('density.'.length)
    const scopes = /^(control-(sm|md|lg)|item)$/.test(short) ? ['WIDTH_HEIGHT'] : ['GAP']
    const id = variable(densityId, short, 'FLOAT', cssVar(short), scopes, token.description)
    for (const mode of DENSITY_MODES) set(id, `mode:density:${mode}`, token.px[mode])
  }

  const colourId = collection('colour', 'nimki/colour', [...COLOUR_MODES])
  for (const colour of theme.colours) {
    const name = colour.token.startsWith('color.')
      ? colour.token.slice('color.'.length)
      : colour.token.split('.').join('/')
    const id = variable(colourId, name, 'COLOR', colour.cssVar, colourScopes(name))
    for (const mode of COLOUR_MODES) {
      // An alias in the CSS stays an alias in Figma; a value or a derived colour
      // becomes its resolved colour, since Figma has no relative colour.
      set(id, `mode:colour:${mode}`, aliasOrValue(colour.css[mode], toSrgb(colour.value[mode])))
    }
  }

  const themeId = collection('theme', 'nimki/theme', ['linear'])
  const t = 'mode:theme:linear'
  set(variable(themeId, 'radius', 'FLOAT', '--radius', ['CORNER_RADIUS']), t, theme.radiusPx)
  for (const font of theme.fonts) {
    // A Figma font variable names one family; the fallbacks exist only in CSS.
    const id = variable(themeId, font.token.split('.').join('/'), 'STRING', font.cssVar, [
      'FONT_FAMILY',
    ])
    set(id, t, font.families[0] as string)
  }
  for (const amount of theme.amounts) {
    // Percent, as the CSS writes it: 8 here is 8% there.
    const id = variable(themeId, amount.token.split('.').join('/'), 'FLOAT', amount.cssVar, [])
    set(id, t, Number((amount.value * 100).toFixed(4)))
  }

  return JSON.stringify(
    {
      variableCollections: collections,
      variableModes: modes,
      variables,
      variableModeValues: values,
    },
    null,
    2,
  )
}

function colourScopes(name: string): string[] {
  if (/(^|-)foreground$/.test(name)) return ['TEXT_FILL', 'SHAPE_FILL']
  if (/^(border|input|ring)$/.test(name)) return ['STROKE_COLOR']
  if (/^(destructive|nk\/success|nk\/warning)$/.test(name)) {
    return ['TEXT_FILL', 'SHAPE_FILL', 'FRAME_FILL', 'STROKE_COLOR']
  }
  return ['FRAME_FILL', 'SHAPE_FILL']
}

function themeBlock(selector: string, lines: string[]): string {
  return block(selector, lines)
}

/**
 * registry/styles/theme-linear.css: the Linear theme's values for shadcn's
 * variables, the radius and nimki's own fonts. Optional: a project that sets
 * these variables itself keeps its own (FR-V2).
 */
export function themeCss(theme: Theme): string {
  const shadcn = theme.colours.filter(colour => colour.token.startsWith('color.'))
  const lines = (mode: (typeof COLOUR_MODES)[number]) =>
    shadcn.map(colour => `${colour.cssVar}: ${colour.css[mode]};`)
  return [
    `/* ${NOTICE} */`,
    '',
    themeBlock(':root', [
      ...lines('light'),
      `--radius: ${Number((theme.radiusPx / 16).toFixed(4))}rem;`,
      ...theme.fonts.map(font => `${font.cssVar}: ${fontCss(font.families)};`),
    ]),
    '',
    themeBlock('.dark', lines('dark')),
    '',
  ].join('\n')
}

/**
 * registry/styles/extensions.css: the --nk- colours and amounts every component
 * reads (FR-V3). Each is derived from shadcn's variables, so it follows the
 * project's theme; dark mode follows shadcn's .dark class (FR-V4).
 */
export function extensionsCss(theme: Theme): string {
  const nk = theme.colours.filter(colour => colour.token.startsWith('nk.'))
  return [
    `/* ${NOTICE} */`,
    '',
    themeBlock(':root', [
      ...nk.map(colour => `${colour.cssVar}: ${colour.css.light};`),
      ...theme.amounts.map(
        amount => `${amount.cssVar}: ${Number((amount.value * 100).toFixed(4))}%;`,
      ),
    ]),
    '',
    themeBlock(
      '.dark',
      nk
        .filter(colour => colour.css.dark !== colour.css.light)
        .map(colour => `${colour.cssVar}: ${colour.css.dark};`),
    ),
    '',
  ].join('\n')
}
